const TIME_LIMIT: int = 3728;
const TH15_FIREBALL_RED: int = 752;
// funcSet4 approximation: center-distance <=40px; every source projectile here is REACT=1.
// No task per bullet: per-effect reads retain continuous entrance/exit response without task-pool loss.
const NEAR_RADIUS: fx = 40fx;
xformdef INFERNO {
    // Source has no age-based deletion; survive until offscreen or the phase clear.
    set_life(65535);
slow_wait:
    @1 set_speed(at_effect($self_speed * (1fx - 0.02fx * (dist($self_x-$player_x, $self_y-$player_y) <= NEAR_RADIUS))));
    loop(slow_wait, 600);
    // Source 1156/1192 VELTIME: logical initial scalar 1.5, target2, duration120.
    // funcSet4 changes the velocity vector; retain its independent delta=(2-1.5)/120.
    // Fixed-point synthetic composition: damping before along-angle acceleration in phase4.
    set_accel(0.5fx / 120);
slow_ramp:
    @1 set_speed(at_effect($self_speed * (1fx - 0.02fx * (dist($self_x-$player_x, $self_y-$player_y) <= NEAR_RADIUS))));
    loop(slow_ramp, 120);
    set_accel(0fx);
slow_tail:
    @1 set_speed(at_effect($self_speed * (1fx - 0.02fx * (dist($self_x-$player_x, $self_y-$player_y) <= NEAR_RADIUS))));
    goto slow_tail;
}

sub ring(secondary: int) {
    var n: int = 144;
    if global(GVAR_RANK) == 0 { n = 64; }
    if secondary != 0 {
        n = 64;
        if global(GVAR_RANK) >= 2 { n = 32; }
    }
    if $frame < self_int(1) {
        // BossCard3_at/at2: source1128-1158/1164-1194; mode3 ring, one shared RANDRAD per call.
        sh_reset(0);
        sh_sprite(0, TH15_FIREBALL_RED, 0);
        sh_ring(0, 1);
        sh_count(0, n, 1);
        sh_speed(0, 1.5fx, 0fx);
        sh_angle(0, (rand(65536)-32768) as angle, 0deg);
        // Source ANIM1 birth stage omitted; retain -4*velocity displacement (-6px).
        // BRIGHT visual omitted; REACT1 represented by attaching INFERNO only to these bullets.
        sh_dist(0, -6fx);
        sh_xform(0, INFERNO);
        sh_fire(0);
    }
}

sub wander() {
    // Source1114 moveRand(30,4,1): speed-mode0 was explicitly reset at1047.
    // Shared movement recipe; limit center(0,144), full size(240,64).
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -60fx {
        a = r/3;
    } else if $self_x > 60fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; }
    } else {
        a = r/4;
        var choose: int = rand(65536)%3;
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
    }
    if $self_y < 128fx {
        if a < 0 { a = -a; }
    } else if $self_y > 160fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    for k in 1..31 {
        var speed: fx = (30-k) as fx / 30;
        var nx: fx = $self_x + speed*cos(a as angle);
        var ny: fx = $self_y + speed*sin(a as angle);
        if nx < -120fx { nx = -120fx; }
        if nx > 120fx { nx = 120fx; }
        if ny < 112fx { ny = 112fx; }
        if ny > 176fx { ny = 176fx; }
        move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
        wait(1);
    }
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    wait(10); // source1115 wait40 includes the30 movement ticks.
}

async sub boss() {
    var gap: int = 120;
    var last_gap: int = 80;
    if global(GVAR_RANK) == 3 { gap = 90; last_gap = 70; }
    // Common Boss state: invincible path HP2320, source hitbox48/2, hurtbox40/2.
    // Shared int1 belongs to this card: source-entry clock, independent of task birth offset.
    set_self_int(1, $frame+3604);
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    clear_bullets_at($self_x, $self_y, 640fx, 0); // source1022/1025; prior card absent.
    wait(4); // source1027/1029; timerReset at source4.
    // killAllAsync/enmKillAll: no inherited tasks/enemies in this independent shell.
    clear_bullets_at($self_x, $self_y, 640fx, 0);
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR); // source1046-1048 cancel all old motion.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60); // first source ring at64, 60 ticks after timerReset.
    // Source1068 ANGLE_PLAYER is saved but never consumed; no extra random sample.
    for cycle in 0..1000 {
        if $frame >= self_int(1) { break; }
        ring(0);
        if global(GVAR_RANK) == 3 { wait(30); ring(1); }
        wait(gap);
        ring(0);
        if global(GVAR_RANK) == 3 { wait(30); ring(1); }
        wait(gap);
        ring(0);
        if global(GVAR_RANK) >= 2 { wait(30); ring(1); }
        wait(last_gap);
        if $frame >= self_int(1) { break; }
        wander();
    }
    // Source1052 timeout boundary only; never enter Boss4. Shell ends the card and clears bullets.
    loop { wait(600); }
}
async sub pattern() {
    wait(120);
    _ = spawn_enemy(0fx, 128fx, 2320, 0, 0, 0, boss);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(600); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
